"""Checkout pricing helpers for the webstore service."""


def total_with_tax(subtotal, rate):
    # WS-4821: apply the configured tax rate to the subtotal before charging.
    return round(subtotal * (1 + rate), 2)

from app.pricing import total_with_tax


def test_total_with_tax_applies_rate():
    assert total_with_tax(100.0, 0.1) == 110.0


def test_total_with_tax_zero_rate():
    assert total_with_tax(50.0, 0.0) == 50.0

